"""
Module for commincation with all in cloud testlines.

For retrieval of resources, the following pods/components are used:

VCU: cpnb, cpnrt, (cpue?)
VDU: cprt

"""
from contextlib import contextmanager
from robot.api import logger
import traceback
from taf.ccs.aashell import aashell as AaShellLib
from taf.transport.ssh.connection import connect
from . import tl_config
import re
from future.utils import raise_from


class PythonAaShellLib(AaShellLib):
    """
    This is a thin wrapper providing alias functionality around AaShellLib.
    It is needed, if taf.ccs.aashell is not used from robotframework but from python.
    """

    def __init__(self, **kwargs):
        super(PythonAaShellLib, self).__init__(**kwargs)
        self._aliases = {}

    def set_alias(self, alias, obj):
        """
        Set alias for processing with taf.ccs.aashell
        """
        self._aliases[alias] = obj

    def get_alias_value(self, alias):
        """
        Get alias for processing with taf.ccs.aashell
        """
        return self._aliases[alias]

    def _create_builin(self):
        pass


@contextmanager
def connect_to_cu_master_node(gnb_id):
    """
    Context manager to establish a connection to the CU master node of the testline.

    :param gnb_id: The gnb_id / index in the testline_configuration to identify the node
    """
    ssh_details = tl_config.get_cu_master_node_ssh_details(gnb_id)
    ssh_connection = connect(hostname=ssh_details.addr,
                             username=ssh_details.username,
                             password=ssh_details.password)
    yield ssh_connection

    ssh_connection.disconnect()


@contextmanager
def connect_to_vdu_master_node(gnb_id=0, vdu_id=0):
    """
    Context manager to establish a connection to a VDU master node of the testline.

    :param gnb_id: The id/index of the gnb in the testline_configuration.
    :paran gdu_id: The id/index of the vdu from testline_configuration.
    """
    ssh_details = tl_config.get_vdu_master_node_ssh_details(gnb_id, vdu_id)
    ssh_connection = connect(hostname=ssh_details.addr,
                             username=ssh_details.username,
                             password=ssh_details.password)
    yield ssh_connection

    ssh_connection.disconnect()


def get_listening_pod_ports(namespace, pod, container, master_connection):
    """
    Find the listening ports for a pod starting with 150* to determine, where the aashell
    might be running.

    :param namespace: The kubectl namespace
    :param pod: the pod
    :param container: The container the pod is running on
    :master_connection: The established ssh connection to the master node
    """
    command = "kubectl exec -n {} {} -c {} -- ss -aptunl".format(namespace, pod, container)
    output = master_connection.execute(command=command)
    tcp_ports = [line for line in output.split('\n') if line.startswith('tcp')]
    tcp_ports = [line for line in tcp_ports if '150' in line]
    tcp_ports = [re.search('150[0-9]+', line).group() for line in tcp_ports]
    return tcp_ports


def get_cpnb_listening_ports(gnb_id=0):
    """
    Lists all listening ports (starting with 150) to determine, where the aashell
    might be running for the component cpnb.

    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    with connect_to_cu_master_node(gnb_id) as ssh:
        return get_listening_pod_ports(tl_config.get_cu_namespace(gnb_id),
                                       get_cpnb_pod(ssh, gnb_id),
                                       get_cpnb_container(ssh, gnb_id),
                                       ssh)


def get_pod_names(ssh_connection, namespace):
    """
    Returns all the pod names for the given namespace on the ssh session of a master node

    :param ssh_connectin: An established ssh connection to a master node
    :param namespace: The kubectl namespace to fetch all pod names from.
    """
    kubectl_output = ssh_connection.execute(command='kubectl get pod -n {}'.format(namespace))
    return parse_pods_from_kubectl_output(kubectl_output)


def get_cpnb_pod(ssh_connection, gnb_id):
    """
    Returns the pod name for the cpnb component

    :param ssh_connection: An established ssh connection to the cu master node
    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    pod_names = get_pod_names(ssh_connection, tl_config.get_cu_namespace(gnb_id))
    try:
        return [pod for pod in list(pod_names) if 'cpnb' in pod][0]
    except IndexError:
        logger.warn('No pod name for cpnb found!')
        return ''


def get_cprt_pod(ssh_connection, gnb_id, vdu_id=0):
    """
    Returns the pod name for the cprt component

    :param ssh_connection: An established ssh connection to the VDU master node
    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    pod_names = get_pod_names(ssh_connection, tl_config.get_vdu_namespace(gnb_id, vdu_id))
    try:
        return [pod for pod in list(pod_names) if 'cprt' in pod][0]
    except IndexError:
        logger.warn('No pod name for cprt found!')
        return ''


def get_cpnrt_pod(ssh_connection, gnb_id):
    """
    Returns the pod name for the cpnrt component

    :param ssh_connection: An established ssh connection to the CU master node
    :param gnb_id: The id/index of gNodeB from testline configuration
    """
