def get_container_names(namespace, master_connection):
    """
    Determine the container from a given namespace

    :param namespace: The kubectl namespace
    :param master_connection: the ssh connection to the master node
    """

    command = 'kubectl get pods -n {} -o jsonpath="{{.items[*].spec.containers[*].name}}"'.format(namespace)
    command_output = master_connection.execute(command=command)
    return command_output.split(' ')


def get_cpnb_container(ssh_connection, gnb_id=0):
    """
    Determine the container name of the cpnb component

    :param ssh_connection: the ssh connection to the CU master node
    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    containers = get_container_names(tl_config.get_cu_namespace(gnb_id), ssh_connection)
    try:
        return [container for container in containers if 'cpnb' in container][0]
    except IndexError:
        logger.warn('No container name for cpnb found!')
        return ''


def get_cprt_container(ssh_connection, gnb_id=0, vdu_id=0):
    """
    Determine the container name of the cpnb component

    :param ssh_connection: the ssh connection to the VDU master node
    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    containers = get_container_names(tl_config.get_vdu_namespace(gnb_id, vdu_id), ssh_connection)

    try:
        return [container for container in containers if 'cprt' in container][0]
    except IndexError:
        logger.warn('No container name for cprt found!')
        return ''


def get_list_of_vdu_pods(gnb_id, vdu_id):
    """
    Determine the list of all pods on the VDU

    :param gnb_id: The id/index of gNodeB from testline configuration
    :param vdu_id: The id/index of the VDU of the gNodeB from the testline configuration
    """
    namespace = tl_config.get_vdu_namespace(gnb_id, vdu_id=vdu_id)
    with connect_to_vdu_master_node(gnb_id, vdu_id) as ssh:
        kubectl_output = ssh.execute(command='kubectl get pod -n {}'.format(namespace))

    return parse_pods_from_kubectl_output(kubectl_output)


def get_list_of_cu_pods(gnb_id):
    """
    Determine the list of all pods on the CU

    :param gnb_id: The id/index of gNodeB from testline configuration
    """
    namespace = tl_config.get_cu_namespace(gnb_id)
    with connect_to_cu_master_node(gnb_id) as ssh:
        kubectl_output = ssh.execute(command='kubectl get pod -n {}'.format(namespace))

    return parse_pods_from_kubectl_output(kubectl_output)


def parse_pods_from_kubectl_output(kubectl_output):
    """
    Parses the output from the kubectl command to determine the existing pod names

    :param kubectl_output: The output from the command 'kubectl get pod -n <namespace>'
    """
    output_lines = [line.strip() for line in kubectl_output.split('\n') if line.strip()]
    output_lines = [line for line in output_lines for component in ['cpnrt', 'cpnb', 'cprt'] if component in line]
    pod_names = {line.split()[0] for line in output_lines}
    return pod_names


def create_cpnb_aashell_parameters(node_type='gnb', node_id=0):
    """
    Create the parameters needed for the aashell to comunicate to the aashell of CPNB

    :param node_id: The id/index of gNodeB from testline configuration
    :param node_type: the type of node, expected to be gnb.
    """
    test_pc = tl_config.get_test_pc(node_id=node_id, node_type=node_type)
    testp_pc_proxy = {'host': test_pc.default_ssh_connection_details.addr,
                      'user': test_pc.default_ssh_connection_details.username,
                      'password': test_pc.default_ssh_connection_details.password}

    k8s_cu_proxy = tl_config.get_k8s_cu_proxy(node_id)
    k8s_cu_proxy['proxy'] = testp_pc_proxy

    with connect_to_cu_master_node(node_id) as ssh:
        return {'alias': get_cpnb_pod(ssh, gnb_id=node_id),
                'k8s': k8s_cu_proxy,
                'namespace': tl_config.get_cu_namespace(node_id),
                'pod': get_cpnb_pod(ssh, gnb_id=node_id),
                'forwarding_port': 15057,
                'port': 15057}


def create_cprt_aashell_parameters(node_type='gnb', node_id=0):
    """
    Create the parameters needed for the aashell to comunicate to the aashell of CPRT

    :param node_id: The id/index of gNodeB from testline configuration
    :param node_type: the type of node, expected to be gnb.
    """
    test_pc = tl_config.get_test_pc(node_id=node_id, node_type=node_type)
    testp_pc_proxy = {'host': test_pc.default_ssh_connection_details.addr,
                      'user': test_pc.default_ssh_connection_details.username,
                      'password': test_pc.default_ssh_connection_details.password}

    k8s_vdu_proxy = tl_config.get_k8s_vdu_proxy(node_id, vdu_id=0)
    k8s_vdu_proxy['proxy'] = testp_pc_proxy

    with connect_to_vdu_master_node(node_id) as ssh:
        return {'alias': get_cprt_pod(ssh, gnb_id=node_id, vdu_id=0),
                'k8s': k8s_vdu_proxy,
                'namespace': tl_config.get_vdu_namespace(node_id, vdu_id=0),
                'pod': get_cprt_pod(ssh, gnb_id=node_id, vdu_id=0),
                'forwarding_port': 15057,
                'port': 15057}


def create_cpnrt_aashell_parameters(node_type='gnb', node_id=0):
    """
    Create the parameters needed for the aashell to comunicate to the aashell of CPNRT

    :param node_id: The id/index of gNodeB from testline configuration
    :param node_type: the type of node, expected to be gnb.
    """
    test_pc = tl_config.get_test_pc(node_id=node_id, node_type=node_type)
    testp_pc_proxy = {'host': test_pc.default_ssh_connection_details.addr,
                      'user': test_pc.default_ssh_connection_details.username,
                      'password': test_pc.default_ssh_connection_details.password}

    k8s_cu_proxy = tl_config.get_k8s_cu_proxy(node_id)
    k8s_cu_proxy['proxy'] = testp_pc_proxy

    with connect_to_cu_master_node(node_id) as ssh:

        cpnrt_pod = get_cpnrt_pod(ssh, gnb_id=node_id)

        return {'alias': cpnrt_pod,
                'k8s': k8s_cu_proxy,
                'namespace': tl_config.get_cu_namespace(node_id),
                'pod': cpnrt_pod,
                'forwarding_port': 15057,
                'port': 15057}


@contextmanager
def aashell_context_for_pod(alias, pod_parameters, port):
    """
    This function provides a context manager for creating the aashell cli for
    any kind of operations.

    :param alias: The alias for the taf.ccs.aashell creation
    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """
    aashell_lib = PythonAaShellLib()

    try:
        aashell_lib.create_aashell_cli(name=pod_parameters['alias'],
                                       hops=pod_parameters['k8s'],
                                       namespace=pod_parameters['namespace'],
                                       pod=pod_parameters['pod'],
                                       forwarding_port=pod_parameters['forwarding_port'],
                                       port=port)

        aashell_lib.setup(alias=alias)
    except Exception as err:
        logger.error('Exception occurred in creation of aashell_context!')
        logger.error(traceback.format_exc())
        raise_from(AssertionError("Error in creation of AAshellContext: {}".format(err)), err)

    yield aashell_lib
    aashell_lib.teardown(alias=alias)


def collect_resources_from_cpnb(node_type='gnb', node_id=0):
    """
    Collect the resources for the CPNB component on the cloud line

    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """

    listening_ports = get_cpnb_listening_ports()
    logger.info("Listening Ports for CPNB: {}".format(listening_ports))

    cpnb_params = create_cpnb_aashell_parameters(node_type=node_type, node_id=node_id)
    logger.info("CPNB Parameters: {}".format(cpnb_params))

    with aashell_context_for_pod(cpnb_params['alias'], cpnb_params, cpnb_params['port']) as aashell:

        cpnb_resources = aashell.get_resources_usage(name=cpnb_params['alias'], detailed=False)

    if 'CPCELL' not in cpnb_resources.keys():
        logger.warn('CPCELL resources not detected collecting for cpnb! [{}]'.format(list(cpnb_resources.keys())))

    if 'CPUE' not in cpnb_resources.keys():
        logger.warn('CPUE resources not detected collecting for cpnb! [{}]'.format(list(cpnb_resources.keys())))

    return cpnb_resources


def collect_resources_from_cprt(node_type='gnb', node_id=0):
    """
    Collect the resources for the CPRT component on the cloud line

    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """
    cprt_params = create_cprt_aashell_parameters(node_type=node_type, node_id=node_id)

    logger.info("CPRT Parameters: {}".format(cprt_params))
    with aashell_context_for_pod(cprt_params['alias'], cprt_params, cprt_params['port']) as aashell:

        cprt_resources = aashell.get_resources_usage(name=cprt_params['alias'], detailed=False)

    if 'CPRT' not in cprt_resources:
        logger.warn('CPRT resources not detected collecting for cprt [{}]'.format(list(cprt_resources.keys())))

    return cprt_resources


def collect_resources_from_cpnrt(node_type='gnb', node_id=0):
    """
    Collect the resources for the CPCRT component on the cloud line

    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """
    cpnrt_params = create_cpnrt_aashell_parameters(node_type=node_type, node_id=node_id)
    logger.info("CPNRT Parameters: {}".format(cpnrt_params))

    with aashell_context_for_pod(cpnrt_params['alias'], cpnrt_params, cpnrt_params['port']) as aashell:

        cpnrt_resources = aashell.get_resources_usage(name=cpnrt_params['alias'], detailed=False)

    if 'CPNRT' not in cpnrt_resources:
        logger.warn('CPNRT resources not detected collecting for cpnrt [{}]'.format(list(cpnrt_resources.keys())))

    return cpnrt_resources


def collect_resources_from_cloud(node_type='gnb', node_id=0):
    """
    Collect the resources for all component from the cloud bts

    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """
    cloud_resources = {}

    data_cprt = collect_resources_from_cprt(node_type=node_type, node_id=node_id)
    cloud_resources.update(data_cprt)

    data_cpnrt = collect_resources_from_cpnrt(node_type=node_type, node_id=node_id)
    cloud_resources.update(data_cpnrt)

    data_cpnb = collect_resources_from_cpnb(node_type=node_type, node_id=node_id)
    cloud_resources.update(data_cpnb)

    return cloud_resources
